<?php /** One day (screen sales-day-view). Data: day, date, dayPart, items, checks, mods, run, depleted, seesCost, mayRun, mayVoid, mayMap, tz, notice, back */ $here = here_url(); ?>
<?= view('shared/header.php', ['id' => 'sales-day-view', 'title' => 'Sales · ' . format_date($date), 'crumbs' => [['Home', '/'], ['Sales by day', '/sales/'], [format_date($date), null]], 'back' => $back]) ?>
<div class="main-content" id="sales-day-view-content">
    <?= view('shared/notice.php', ['notice' => $notice]) ?>
    <div class="row g-2 mb-3" id="day-tiles">
        <?php foreach (['checks' => 'Checks', 'covers' => 'Covers'] as $k => $l): ?><div class="col-6 col-sm-4"><div class="card mb-0"><div class="card-body p-2 text-center"><div class="fs-4 fw-semibold" id="day-tile-<?= $k ?>"><?= (int) $day[$k] ?></div><div class="fs-11 text-muted"><?= $l ?></div></div></div></div><?php endforeach; ?>
        <div class="col-12 col-sm-4"><div class="card mb-0"><div class="card-body p-2 text-center"><div class="fs-4 fw-semibold" id="day-tile-net"><?= e(ri_money($day['net'])) ?></div><div class="fs-11 text-muted">Net</div></div></div></div>
    </div>
    <div class="chip-row mb-3" id="day-parts"><?= hx_link('/sales/' . $date, 'Whole day', 'badge ' . ($dayPart === null ? 'bg-primary' : 'bg-soft-light text-dark border'), 'id="day-part-all"') ?><?php foreach ($day['day_parts'] as $p): ?><span class="badge bg-soft-light text-dark border"><?= e($p['day_part'] ?? 'no day part') ?>: <?= (int) $p['checks'] ?> check<?= (int) $p['checks'] === 1 ? '' : 's' ?></span><?php endforeach; ?></div>
    <?= view('pos/_run-card.php', ['run' => $run, 'date' => $date, 'seesCost' => $seesCost, 'mayRun' => $mayRun, 'mayVoid' => $mayVoid, 'tz' => $tz]) ?>
    <?php if ($day['due'] && $run !== null && $run['status'] !== 'void'): ?><div class="alert alert-warning fs-12" id="day-due">Sales arrived (or a PLU was mapped) after this run — re-run the day.</div><?php endif; ?>
    <div class="row g-3">
        <div class="col-lg-6">
            <div class="card mb-3" id="day-items"><div class="card-header"><h5 class="card-title mb-0">Sales by item</h5></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-sm mb-0 fs-12" id="day-items-table"><thead><tr><th>Item</th><th>PLU</th><th class="text-end">Qty</th><th class="text-end">Net</th><th class="text-end">Comps</th><th></th></tr></thead><tbody>
            <?php foreach ($items as $i): $mid = (int) $i['menu_item_id']; ?><tr id="day-item-<?= $mid ?>"><td><?= hx_link('/menu/' . $mid, e($i['name'])) ?></td><td><?= e($i['plu']) ?></td><td class="text-end"><?= e(fmt_num($i['qty'], 2)) ?></td><td class="text-end"><?= e(ri_money($i['net'])) ?></td><td class="text-end"><?= e(fmt_num($i['comps_qty'], 2)) ?></td>
                <td class="text-end"><?php if ($i['recipe_id'] === null && empty($i['no_depletion'])): ?><?= $mayMap ? hx_link(with_back('/menu/' . $mid . '/map', $here), 'Map', 'btn btn-sm btn-primary btn-touch', 'id="day-item-map-' . $mid . '"') : '<span class="badge bg-soft-danger text-danger">unmapped</span>' ?><?php elseif (!empty($i['no_depletion'])): ?><span class="badge bg-soft-secondary text-secondary">no stock</span><?php endif; ?></td></tr><?php endforeach; ?>
            </tbody></table></div></div></div>
            <div class="card mb-3" id="day-modifiers"><div class="card-header"><h5 class="card-title mb-0">Modifiers</h5></div><div class="card-body p-0"><?php if ($mods === []): ?><div class="p-3 text-muted fs-12">None this day.</div><?php else: ?><table class="table table-sm mb-0 fs-12"><tbody>
            <?php foreach ($mods as $m): ?><tr id="day-mod-<?= (int) $m['modifier_id'] ?>"><td><?= e($m['code']) ?></td><td><?= e($m['name']) ?></td><td class="text-end"><?= e(fmt_num($m['qty'], 2)) ?></td><td><span class="badge <?= $m['action'] === 'none' || $m['recipe_id'] !== null ? 'bg-soft-light text-dark border' : 'bg-soft-danger text-danger' ?>"><?= e($m['action']) ?><?= $m['action'] !== 'none' && $m['recipe_id'] === null ? ' · unmapped' : '' ?></span></td><td class="text-end"><?= $mayMap ? hx_link(with_back('/modifiers/' . (int) $m['modifier_id'] . '/map', $here), 'Map', 'btn btn-sm btn-light btn-touch') : '' ?></td></tr><?php endforeach; ?>
            </tbody></table><?php endif; ?></div></div>
        </div>
        <div class="col-lg-6">
            <div class="card mb-3" id="day-depleted"><div class="card-header"><h5 class="card-title mb-0">What the day depleted</h5></div><div class="card-body p-0"><?php if ($depleted === []): ?><div class="p-3 text-muted fs-12"><?= $run === null ? 'Not depleted yet.' : 'Nothing — no mapped line.' ?></div><?php else: ?><div class="table-responsive"><table class="table table-sm mb-0 fs-12" id="day-depleted-table"><thead><tr><th>Ingredient</th><th class="text-end">Used</th><th>From</th><th class="text-end">Value</th></tr></thead><tbody>
            <?php foreach ($depleted as $d): ?><tr id="day-depleted-<?= (int) $d['ingredient_id'] ?>"><td><?= hx_link('/ingredients/' . (int) $d['ingredient_id'], e($d['name'])) ?></td><td class="text-end"><?= e($d['qty_display']) ?><?= $d['returned'] ? ' <span class="badge bg-soft-info text-info" title="a remove modifier put some back">returned</span>' : '' ?></td><td><?= e((string) $d['areas']) ?></td><td class="text-end"><?= money($seesCost && $d['value'] !== null ? (string) (-(float) $d['value']) : null) ?></td></tr><?php endforeach; ?>
            </tbody></table></div><?php endif; ?></div></div>
            <div class="card mb-3" id="day-checks"><div class="card-header"><h5 class="card-title mb-0">Checks (<?= count($checks) ?>)</h5></div><div class="card-body p-0"><div class="table-responsive"><table class="table table-sm mb-0 fs-12" id="day-checks-table"><thead><tr><th>Check</th><th>Closed</th><th>Part</th><th class="text-end">Covers</th><th class="text-end">Subtotal</th><th></th></tr></thead><tbody>
            <?php foreach ($checks as $c): $sid = (int) $c['sale_id']; ?><tr id="check-row-<?= $sid ?>"><td><?= e($c['external_id']) ?></td><td><?= $c['closed_at'] === null ? '—' : e(format_ts((string) $c['closed_at'], $tz, 'g:i A')) ?></td><td><?= e($c['day_part'] ?? '—') ?></td><td class="text-end"><?= $c['covers'] === null ? '' : (int) $c['covers'] ?></td><td class="text-end"><?= e(ri_money($c['subtotal'])) ?></td>
                <td class="text-end"><a href="/sales/<?= e($date) ?>?check=<?= $sid ?>" hx-get="/sales/<?= e($date) ?>?check=<?= $sid ?>" hx-target="#check-lines-<?= $sid ?>" hx-swap="innerHTML" class="btn btn-sm btn-light btn-touch" id="check-expand-<?= $sid ?>"><?= (int) $c['line_count'] ?> line<?= (int) $c['line_count'] === 1 ? '' : 's' ?></a></td></tr>
                <tr class="check-lines-row"><td colspan="6" class="p-0" id="check-lines-<?= $sid ?>"></td></tr><?php endforeach; ?>
            </tbody></table></div></div></div>
        </div>
    </div>
</div>
